/**
 * Returns the memoized (cached) function.
 * @param fn
 */
const memorize = (fn) => {
    const cache = new Map();
    const cached = function (val) {
        // @ts-ignore
        return cache.has(val)
            ? cache.get(val)
            : // @ts-ignore
                cache.set(val, fn.call(this, val)) && cache.get(val);
    };
    cached.cache = cache;
    return cached;
};
export default memorize;
